# Problem: longest common prefix among list of strings.
# Linear scan: start with first string as prefix; shrink at first mismatch.
# Amortized linear time; clean and efficient.
def longest_common_prefix(strs):
    if not strs:
        return ''
    prefix = strs[0]
    for s in strs[1:]:
        while not s.startswith(prefix):
            prefix = prefix[:-1]
            if not prefix:
                return ''
    return prefix
```

