# Problem: anagram check — same multiset of characters.
# Hash-map count: linear time, linear space.
def valid_anagram(s, t):
    if len(s) != len(t):
        return False
    counts = {}
    for c in s:
        counts[c] = counts.get(c, 0) + 1
    for c in t:
        if counts[c] == 0:
            return False
        counts[c] -= 1
    return True
```

